<span class="line"><span style="color:#E5C07B;">il</span><span style="color:#ABB2BF;">.</span><span style="color:#61AFEF;">Emit</span><span style="color:#ABB2BF;">(</span><span style="color:#E5C07B;">OpCodes</span><span style="color:#ABB2BF;">.</span><span style="color:#E5C07B;">Stloc</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;">localInt</span><span style="color:#ABB2BF;">);    </span><span style="color:#7F848E;font-style:italic;">// 存储</span></span>
